INSERT INTO feature VALUES('secret-never-open','runtime','A secret that never crosses a world, prints or compares','value-crossing','partial','notable',NULL,'A secret is `Secret.T` of `std.secret`, sealed with no mark: `seal` puts text in and no member reads it back. A migration''s result or capture holding one is refused `Immobile` before the wire is touched, a run answering one prints `⟨opaque at Secret⟩ : T`, and comparing two is refused `ModelUnanswered`, naming `Secret.T`. A site names its key''s secret, and `gandr host --site` reads it through the `Secrets` model `--secrets` names, a pure model the user writes, or from `GANDR_SECRET_<NAME>`, refusing a secret that is missing, spells no key or proves another key without spelling it, and `--net-secret` beside the site. A theory requiring `Secrets` is owed (#6546), and so is a host interface carrying a secret (#2901).','core-checker surface-dispatcher surface-diagnostics surface-driver','corpus/ledger/features/secret-never-open.gandr corpus/pathological/worlds/secret-crosses.gandr corpus/model/worlds/two-processes.secrets.gandr crates/surface-dispatcher/tests/manifold.rs crates/surface-driver/tests/net.rs','corpus/ledger/features/secret-never-open.gandr','#6546 #2901');
